"""Class 6 Maths Ch 9 - Symmetry."""
from g67 import *

SLUG, NAME, CHNO = "Symmetry", "Symmetry", 9
SHAPES = {"equilateral triangle": 3, "square": 4, "regular pentagon": 5, "regular hexagon": 6, "regular octagon": 8, "regular decagon": 10, "regular nonagon": 9, "regular 12-gon": 12}
POLY = {k: v for k, v in SHAPES.items()}
VERT = "AHIMOTUVWXY"; HORZ = "BCDEHIKOX"; ROT = "HINOSXZ"; NOSYM = "FGJLPQR"
def tc(q, a, w, why="Symmetry property"): return tm(q, a, w, why)
def nl(q, c, why, offs=(1, -1, 2, 3, 4), **kw): return nm(q, c, why, offs, **kw)
def pick(s, k, off=0): return [s[(off + i) % len(s)] for i in range(k)]
def lt(xs): return ", ".join(xs)

# ---------- EASY ----------
eA1 = [nl(f"The number of lines of symmetry of a {k} is:", v, f"A regular polygon with {v} sides has {v} lines of symmetry.") for k, v in [("square", 4), ("equilateral triangle", 3), ("regular hexagon", 6), ("regular pentagon", 5), ("regular octagon", 8)]]
eA2 = [nl(f"The number of lines of symmetry of the capital letter {ch} is:", n, f"Letter {ch}.", offs=(1, -1, 2, 3)) for ch, n in [("A", 1), ("H", 2), ("T", 1), ("E", 1), ("X", 2)]]
eA3 = [tc("Which of these letters has no line of symmetry?", ch, w, "It cannot be folded into two matching halves.") for ch, w in [("F", ["A", "H", "T"]), ("G", ["M", "O", "U"]), ("J", ["H", "V", "X"]), ("L", ["I", "W", "Y"]), ("P", ["B", "E", "D"])]]
eA4 = [nl(f"The angle of rotation of a figure with rotational symmetry of order {n} is (degrees):", 360 // n, "Angle $=360^\\circ\\div$ order.", offs=(10, -10, 30, 60, 90)) for n in [2, 3, 4, 6, 8]]
eA5 = [tc(q, a, w) for q, a, w in [("A circle has:", "infinitely many lines of symmetry", ["one line of symmetry", "four lines of symmetry", "no line of symmetry"]), ("A rectangle (not a square) has how many lines of symmetry?", "2", ["1", "4", "0"]), ("A scalene triangle has how many lines of symmetry?", "0", ["1", "2", "3"]), ("An isosceles triangle has how many lines of symmetry?", "1", ["0", "2", "3"]), ("The mirror image of a figure is also called its:", "reflection", ["rotation", "area", "perimeter"])]]
eA6 = [nl(f"A figure is rotated through a full turn. It coincides with itself how many times in one full turn if its order of rotational symmetry is {n}?", n, "Order = number of times it fits.", offs=(1, -1, 2, 3)) for n in [3, 4, 5, 6, 12]]
EASY_A = [eA1, eA2, eA3, eA4, eA5, eA6]
EASY_B = ([QQ(f"How many lines of symmetry does a {k} have?", f"A regular polygon has as many lines as sides", f"{v} lines") for k, v in [("square", 4), ("regular hexagon", 6), ("equilateral triangle", 3), ("regular pentagon", 5)]]
          + [QQ(f"Write the angle of rotational symmetry of a {k}.", f"Angle $=360^\\circ\\div{v}$", f"${360//v}^\\circ$") for k, v in [("square", 4), ("regular hexagon", 6), ("equilateral triangle", 3), ("regular octagon", 8)]]
          + [QQ(f"Which of the letters {lt(pick('AHBFTXMG', 5, i))} have a vertical line of symmetry?", "Fold along a vertical line", lt([c for c in pick('AHBFTXMG', 5, i) if c in VERT]) or "None") for i in [0, 1, 2, 3]])
EASY_C = ([QQ(f"State the number of lines of symmetry and order of rotational symmetry of a {k}.", f"Lines $={v}$", f"Order $={v}$", f"Smallest angle $={360//v}^\\circ$") for k, v in [("square", 4), ("equilateral triangle", 3), ("regular hexagon", 6), ("regular pentagon", 5), ("regular octagon", 8), ("regular decagon", 10)]]
          + [QQ(f"Classify each letter in {lt(pick('AHBCOSXZ', 4, i))} as having a line of symmetry (yes/no).", "Imagine folding the letter", "; ".join(f"{c}: {'yes' if c in VERT or c in HORZ else 'no'}" for c in pick('AHBCOSXZ', 4, i)), "Check each fold") for i in range(6)]
          + [QQ(f"Draw (describe) the mirror image of the point at {a} units to the left of a vertical mirror line. How far is its image from the mirror?", "A mirror image is at equal distance on the other side", f"The image is {a} units to the right of the mirror", f"Distance between point and image $=2\\times{a}={2*a}$ units") for a in [2, 3, 4, 5, 6, 7]])
EASY_D = ([QQ(f"A regular polygon has {n} sides. Write its number of lines of symmetry, its order of rotational symmetry and its smallest angle of rotation. Name the polygon.", f"Lines of symmetry $={n}$", f"Order $={n}$", f"Angle $=360\\div{n}={360//n}^\\circ$", f"The polygon is a {n}-sided regular polygon") for n in [3, 4, 5, 6, 8, 12]]
          + [QQ(f"Which of the letters {lt(pick('HOXZNSIAT', 5, i))} have (a) both vertical and horizontal lines of symmetry, (b) rotational symmetry of order 2?", "Check both folds", "(a) " + (lt([c for c in pick('HOXZNSIAT', 5, i) if c in VERT and c in HORZ]) or "none"), "(b) " + (lt([c for c in pick('HOXZNSIAT', 5, i) if c in ROT]) or "none"), "Order 2 means it fits after a half turn") for i in range(6)])

# ---------- NCERT ----------
nA1 = [tc("A rhombus (not a square) has how many lines of symmetry?", "2", ["1", "4", "0"], "Along its two diagonals.")] + [tc(q, a, w) for q, a, w in [("A parallelogram (not a rectangle or rhombus) has how many lines of symmetry?", "0", ["1", "2", "4"]), ("A kite has how many lines of symmetry?", "1", ["0", "2", "4"]), ("An isosceles trapezium has how many lines of symmetry?", "1", ["0", "2", "4"]), ("The order of rotational symmetry of a rhombus (not a square) is:", "2", ["1", "4", "3"])]]
nA2 = [nl(f"The smallest angle through which a {k} must be rotated to coincide with itself is (degrees):", 360 // v, "$360^\\circ\\div$ number of sides.", offs=(10, -10, 30, 60, 90)) for k, v in [("regular pentagon", 5), ("regular hexagon", 6), ("regular nonagon", 9), ("regular decagon", 10), ("regular octagon", 8)]]
nA3 = [tc(f"The mirror image of the letter {ch} in a vertical mirror to its right looks like:", "the same letter" if ch in VERT else "a reversed letter", ["the same letter" if ch not in VERT else "a reversed letter", "an upside-down letter", "a different letter"][:3], "Vertical-axis symmetry keeps it the same.") for ch in "AMTHJ"][:5]
nA4 = [nl(f"A figure coincides with itself after turns of {', '.join(str(360//n*i) for i in range(1, 4))}, ... degrees, up to a full turn of 360$^\\circ$. Its order of rotational symmetry is:", n, "Order = $360\\div$ smallest angle.", offs=(1, -1, 2, 3)) for n in [4, 5, 6, 8]]
nA5 = [nl(f"A regular polygon has {n} lines of symmetry. The number of its sides is:", n, "Sides = lines of symmetry.", offs=(1, -1, 2, 3)) for n in [7, 9, 11, 12]]
nA6 = [tc(f"Which of these letters has rotational symmetry of order 2 but NO line of symmetry?", "Z", ["H", "O", "A"], "Z fits after a half turn but cannot be folded."), tc("Which of these letters has both a vertical and horizontal line of symmetry?", "H", ["A", "S", "N"], "H has two fold lines."), tc("Which of these letters has only a horizontal line of symmetry?", "C", ["A", "H", "S"], "Fold along the horizontal middle."), tc("Which of these has no symmetry at all?", "F", ["H", "O", "X"], "No line, no rotation.")]
nA7 = [nl(f"The smallest angle of rotation of a figure is {a}$^\\circ$. Its order of rotational symmetry is:", 360 // a, "Order $=360^\\circ\\div$ angle.", offs=(1, -1, 2, 3)) for a in [45, 60, 72, 90, 120]]
NCERT_A = [nA1, nA2, nA3, nA4, nA5, nA6, nA7]
NCERT_B = ([QQ(f"Draw (describe) all lines of symmetry of a {k}.", "Fold the figure so that the two halves coincide", f"There are {v} lines of symmetry", "Lines pass through vertices/midpoints as per the shape") for k, v in [("rectangle (not square)", 2), ("rhombus (not square)", 2), ("isosceles triangle", 1), ("kite", 1)]]
           + [QQ(f"Find the angle of rotational symmetry and order for a regular polygon of {n} sides.", f"Angle $=360\\div{n}$", f"${360//n}^\\circ$ and order {n}") for n in [5, 9, 10, 12]]
           + [QQ(f"Write the mirror image of the word {w} in a vertical mirror (the reflection reads reversed) and say if the word looks the same.", "Reverse the order of letters and reflect each letter", f"Reversed order: {w[::-1]}", "Looks the same" if all(c in VERT for c in w) and w == w[::-1] else "Does not look the same") for w in ["MAM", "TOT", "WOW", "HAT"]])
NCERT_C = ([QQ(f"A regular polygon has rotational symmetry of angle {a}$^\\circ$. How many sides does it have, and how many lines of symmetry?", f"Sides $=360\\div{a}={360//a}$", f"Lines of symmetry $={360//a}$", "Order of rotational symmetry equals the number of sides") for a in [40, 45, 60, 72, 90, 120]]
           + [QQ(f"For the capital letter {ex}, state whether it has (i) a vertical line of symmetry, (ii) a horizontal line of symmetry, (iii) rotational symmetry of order 2.", f"(i) Vertical line: {'yes' if ex in VERT else 'no'}", f"(ii) Horizontal line: {'yes' if ex in HORZ else 'no'}", f"(iii) Rotational symmetry of order 2: {'yes' if ex in ROT else 'no'}") for ex in "AMSZTN"]
           + [QQ(f"A point P is {a} units above a horizontal mirror line. Where is its image and how far apart are P and its image?", "Image is the same distance behind the mirror", f"Image is {a} units below the line", f"Distance $={2*a}$ units") for a in [3, 4, 5, 6, 7, 8]])
NCERT_D = ([QQ(f"Study the shape: a regular {k}. Write (a) number of lines of symmetry, (b) order of rotational symmetry, (c) smallest angle of rotation, (d) the angle after {m} such rotations.", f"(a) ${v}$", f"(b) ${v}$", f"(c) ${360//v}^\\circ$", f"(d) ${m}\\times{360//v}={m*360//v}^\\circ$") for k, v, m in [("hexagon", 6, 4), ("octagon", 8, 3), ("pentagon", 5, 2), ("nonagon", 9, 4), ("decagon", 10, 3), ("12-gon", 12, 5)]]
           + [QQ(f"Letters of the word {w}: find which letters have vertical symmetry, which have horizontal symmetry and which have rotational symmetry of order 2. Is the word itself symmetric about a vertical mirror?", "Letters with vertical symmetry: " + (lt([c for c in w if c in VERT]) or "none"), "Letters with horizontal symmetry: " + (lt([c for c in w if c in HORZ]) or "none"), "Order-2 rotational letters: " + (lt([c for c in w if c in ROT]) or "none"), "Word symmetric (vertical): " + ("yes" if all(c in VERT for c in w) and w == w[::-1] else "no")) for w in ["MATH", "TOOT", "WOW", "NOON", "OXO", "HIM"]])

# ---------- MEDIUM ----------
mA1 = [nl(f"A regular polygon has each angle of rotation ${360//n}^\\circ$. The number of lines of symmetry is:", n, "Lines of symmetry = $360\\div$ angle.", offs=(1, -1, 2, 3)) for n in [18, 20, 24, 30]]
mA2 = [nl(f"The total angle through which a regular {k} turns when rotated {m} times through its smallest angle (degrees):", m * 360 // v, "Multiply.", offs=(10, -10, 30, 360)) for k, v, m in [("hexagon", 6, 5), ("octagon", 8, 5), ("pentagon", 5, 3), ("nonagon", 9, 4)]]
mA3 = [tc("A figure has 4 lines of symmetry. Which could it be?", "A square", ["A rectangle", "A rhombus (not a square)", "A scalene triangle"], "Only the square among these has 4."), tc("A figure has 6 lines of symmetry. It could be a regular:", "hexagon", ["pentagon", "octagon", "square"], "6 lines mean 6 sides."), tc("A figure with rotational symmetry of order 3 and 3 lines of symmetry is a(n):", "equilateral triangle", ["square", "rhombus", "kite"], "Equilateral triangle."), tc("A figure with only one line of symmetry and no rotational symmetry (order 1) is an:", "isosceles triangle", ["square", "circle", "equilateral triangle"], "A turn of 360 degrees is the only turn that fits.")]
mA3 = [tc("A figure has 4 lines of symmetry. Which could it be?", "A square", ["A rectangle", "A rhombus (not a square)", "A scalene triangle"], "Only the square among these has 4."), tc("A figure has 6 lines of symmetry. It could be a regular:", "hexagon", ["pentagon", "octagon", "square"], "6 lines mean 6 sides."), tc("A figure with rotational symmetry of order 3 and 3 lines of symmetry is a(n):", "equilateral triangle", ["square", "rhombus", "kite"], "Equilateral triangle."), tc("A figure with only one line of symmetry and no rotational symmetry (order 1) is an:", "isosceles triangle", ["square", "circle", "equilateral triangle"], "A turn of 360 degrees is the only turn that fits.")]
mA4 = [nl(f"A square is rotated about its centre through {a}$^\\circ$. The smallest further turn (degrees) after which it again coincides with itself is:", 90 - a % 90, "The square fits after every multiple of $90^\\circ$.", offs=(10, -10, 90, 5)) for a in [30, 50, 15, 70]]
mA5 = [nl(f"The sum of the number of lines of symmetry of a {k1} and a {k2} is:", POLY[k1] + POLY[k2], "Add.", offs=(1, -1, 2, 5)) for k1, k2 in [("square", "regular hexagon"), ("regular pentagon", "equilateral triangle"), ("regular octagon", "square"), ("regular hexagon", "regular pentagon")]]
mA6 = [nl(f"How many of the letters in {lt(w)} have a line of symmetry?", sum(1 for c in w if c in VERT or c in HORZ), "Count the letters with a fold line.", offs=(1, -1, 2, 3)) for w in ["ABCDE", "FGHIJ", "KLMNO", "PQRST", "UVWXYZ"]]
mA7 = [nl(f"A wheel has {n} equal spokes. The smallest angle of rotation that fits the wheel back on itself is (degrees):", 360 // n, "$360\\div$ spokes.", offs=(10, -10, 30, 15)) for n in [8, 9, 10, 12, 15]]
MED_A = [mA1, mA2, mA3, mA4, mA5, mA6, mA7]
MED_B = ([QQ(f"A regular polygon rotates through ${360//n}^\\circ$ to coincide with itself. How many sides does it have? Name its order of symmetry.", f"Sides $=360\\div{360//n}={n}$", f"Order $={n}$") for n in [9, 10, 12, 15]]
          + [QQ(f"Find the total number of lines of symmetry of a {k1} and a {k2} together.", f"{k1}: {POLY[k1]}", f"{k2}: {POLY[k2]}; total {POLY[k1]+POLY[k2]}") for k1, k2 in [("square", "regular octagon"), ("equilateral triangle", "regular hexagon"), ("regular pentagon", "square"), ("regular decagon", "regular hexagon")]]
          + [QQ(f"A regular {n}-gon is turned about its centre so that vertex A moves to the position of the vertex {k} places further along. Through what angle has it turned?", f"Angle between neighbouring vertices $=360\\div{n}={360//n}^\\circ$", f"Turn $={k}\\times{360//n}={k*360//n}^\\circ$") for n, k in [(6, 2), (8, 3), (9, 4), (10, 3)]])
MED_C = ([QQ(f"A regular polygon has {n} lines of symmetry. Find its angle of rotation, the angle after {k} turns and the number of turns to make a full rotation.", f"Angle $=360\\div{n}={360//n}^\\circ$", f"After {k} turns: ${k*360//n}^\\circ$", f"Turns for full rotation $={n}$") for n, k in [(5, 3), (6, 4), (8, 5), (9, 4), (10, 7), (12, 5)]]
          + [QQ(f"Write the order of rotational symmetry and number of lines of symmetry for the letters {lt(w)}. Which have more lines than the order?", "; ".join(f"{c}: order {2 if c in ROT else 1}, lines {2 if c in 'HIOX' else 1 if c in VERT or c in HORZ else 0}" for c in w), "Compare each pair", "Counting complete") for w in ["HAT", "OXZ", "TIN", "MOS", "XYZ", "SHO"]]
          + [QQ(f"A clock face has {n} equally spaced marks. State the number of lines of symmetry (through marks) and the angle between neighbouring marks. If the minute hand moves from mark 0 to mark {m}, through what angle has it turned?", f"Angle between marks $=360\\div{n}={360//n}^\\circ$", f"Lines of symmetry $={n}$ for a regular arrangement", f"Turn to mark {m}: ${m*360//n}^\\circ$") for n, m in [(12, 5), (8, 3), (10, 4), (6, 5), (9, 2), (15, 4)]])
MED_D = ([QQ(f"A rangoli is a regular {n}-pointed pattern. Find (a) its lines of symmetry, (b) the smallest rotation angle, (c) how many rotations of that angle bring it back to the start, (d) whether a rotation of ${k*360//n}^\\circ$ leaves it unchanged.", f"(a) {n}", f"(b) ${360//n}^\\circ$", f"(c) {n}", f"(d) ${k*360//n}^\\circ$ is {k} turns so it leaves the pattern unchanged") for n, k in [(5, 2), (6, 3), (8, 3), (9, 4), (10, 7), (12, 5)]]
          + [QQ(f"Compare a {a} and a {b}: find the angle of rotation of each, say which is larger, find the difference of the two angles, and the total number of lines of symmetry of the two figures together.", f"{a}: ${360//POLY[a]}^\\circ$", f"{b}: ${360//POLY[b]}^\\circ$", f"Larger angle: {a if 360//POLY[a] > 360//POLY[b] else b}; difference $={abs(360//POLY[a]-360//POLY[b])}^\\circ$", f"Total lines $={POLY[a]}+{POLY[b]}={POLY[a]+POLY[b]}$") for a, b in [("square", "regular octagon"), ("equilateral triangle", "regular hexagon"), ("regular pentagon", "regular decagon"), ("square", "regular hexagon"), ("regular hexagon", "regular 12-gon"), ("regular pentagon", "regular octagon")]])

# ---------- HARD ----------
hA1 = [nl(f"A regular polygon has an angle of rotation ${a}^\\circ$ and its perimeter is {s*360//a} cm. The side length is (cm):", s, "Number of sides $=360\\div a$.", offs=(1, -1, 2, 3)) for a, s in [(40, 5), (45, 6), (60, 7), (72, 9)]]
hA2 = [nl(f"After a rotation of ${m*360//n}^\\circ$ a regular {n}-gon coincides with itself. This rotation is {m} times the smallest rotation. The smallest rotation (degrees) is:", 360 // n, "Divide.", offs=(10, -10, 30, 5)) for n, m in [(8, 3), (9, 5), (12, 7), (10, 3)]]
hA3 = [nl(f"The number of letters among {lt(w)} with BOTH a vertical and a horizontal line of symmetry is:", sum(1 for c in w if c in VERT and c in HORZ), "Letters H, I, O, X.", offs=(1, -1, 2, 3)) for w in ["AHBIC", "OXDMT", "HOXIE", "WXYZH"]]
hA4 = [nl(f"The sum of the angles of rotation of a square and a regular {k} (in degrees) is:", 90 + 360 // v, "Add the smallest angles.", offs=(10, -10, 30, 45)) for k, v in [("hexagon", 6), ("octagon", 8), ("pentagon", 5), ("decagon", 10)]]
hA5 = [nl(f"A figure has rotational symmetry of order {n} and one of its lines of symmetry. The total number of lines of symmetry it must have is:", n, "If a figure has a line and order n, it has n lines.", offs=(1, -1, 2, 3)) for n in [3, 5, 6, 8]]
hA6 = [nl(f"A regular polygon has {n} sides. The number of different angles (less than 360$^\\circ$, other than 0) through which it can be turned to coincide with itself is:", n - 1, "Order $n$ gives $n-1$ such turns before a full turn.", offs=(1, -1, 2, 3)) for n in [4, 6, 8, 9]]
hA7 = [nl(f"A regular polygon is rotated again and again through its smallest angle {360//n}$^\\circ$. The number of turns needed to complete a full turn is:", n, "$360\\div$ angle.", offs=(1, -1, 2, 3)) for n in [9, 12, 15, 18]]
hA8 = [nl(f"A regular {n}-gon has side {s} cm. Its perimeter (cm) is:", n * s, "Number of sides times side.", offs=(s, -s, n, 10)) for n, s in [(6, 7), (8, 5), (9, 4)]]
hA9 = [nl(f"The image of a point {a} units from a mirror line is how far from the original point (units)?", 2 * a, "Equal distance on the other side.", offs=(a, -a, 1, 4 * a)) for a in [5, 8, 12]]
HARD_A = [hA1, hA2, hA3, hA4, hA5, hA6, hA7, hA8, hA9]
HARD_B = ([QQ(f"A regular polygon has rotational symmetry with the smallest angle of ${a}^\\circ$ and each side {s} cm. Find the number of sides and its perimeter.", f"Sides $=360\\div{a}={360//a}$", f"Perimeter $={360//a}\\times{s}={360//a*s}$ cm") for a, s in [(30, 4), (36, 5), (24, 6), (20, 3)]]
          + [QQ(f"A figure fits onto itself after turns of ${a}^\\circ$ and ${b}^\\circ$ but not after any smaller turn than ${a}^\\circ$. Find its order of symmetry and show that ${b}^\\circ$ is a multiple of ${a}^\\circ$.", f"Order $=360\\div{a}={360//a}$", f"${b}^\\circ$ is a multiple: {b//a} times {a}") for a, b in [(40, 120), (45, 135), (60, 240), (72, 216)]]
          + [QQ(f"A figure has rotational symmetry of order {n}. List all the angles (up to but not including $360^\\circ$) through which it can be turned to coincide with itself.", f"Smallest angle $=360\\div{n}={360//n}^\\circ$", "Angles: " + ", ".join(str(360//n*i) + "$^\\circ$" for i in range(1, n))) for n in [4, 5, 6, 8]])
HARD_C = ([QQ(f"A designer wants a symmetrical logo with {n} identical petals. Find the angle between neighbouring petals, the number of lines of symmetry and the total of angles around the centre if {n} petals are placed.", f"Angle $=360\\div{n}={360//n}^\\circ$", f"Lines of symmetry $={n}$", f"Total around centre $={n}\\times{360//n}=360^\\circ$") for n in [5, 6, 8, 9, 10, 12]]
          + [QQ(f"A regular polygon has {n} sides ({n} is even). Of its {n} lines of symmetry, how many pass through two opposite vertices and how many pass through the midpoints of two opposite sides?", f"Lines through opposite vertices: ${n}\\div2={n//2}$", f"Lines through midpoints of opposite sides: ${n//2}$", f"Total $={n}$") for n in [4, 6, 8, 10, 12, 14]]
          + [QQ(f"A regular {n}-gon is rotated about its centre by ${t}^\\circ$ anticlockwise and the figure looks unchanged. Verify this using the order of symmetry and find the number of rotations of the smallest angle that make ${t}^\\circ$.", f"Smallest angle $=360\\div{n}={360//n}^\\circ$", f"${t}\\div{360//n}={t//(360//n)}$ rotations", "A whole number means the figure fits") for n, t in [(6, 180), (8, 135), (9, 200), (10, 144), (12, 210), (5, 288)]])
HARD_D = ([QQ(f"For a regular {n}-gon of side {s} cm: (a) find the number of lines of symmetry, (b) the angle of rotation, (c) the perimeter, (d) the angle turned by a vertex when the polygon is rotated {m} times through the smallest angle.", f"(a) {n}", f"(b) ${360//n}^\\circ$", f"(c) ${n*s}$ cm", f"(d) ${m*360//n}^\\circ$") for n, s, m in [(6, 5, 4), (8, 4, 5), (9, 3, 6), (10, 6, 3), (12, 2, 7), (5, 8, 4)]]
          + [QQ(f"Two regular polygons have {a} and {b} sides. Find their smallest angles of rotation, the difference, and the least angle (in degrees) that is a turn for both (the LCM of the two angles).", f"Angles: ${360//a}^\circ$ and ${360//b}^\circ$", f"Difference ${abs(360//a-360//b)}^\circ$", f"LCM of {360//a} and {360//b} is {lcm(360//a,360//b)}", f"Common turn ${lcm(360//a,360//b)}^\circ$") for a, b in [(3, 4), (4, 6), (5, 6), (6, 9), (4, 5), (3, 5)]])

TIERS = T4((NCERT_A, NCERT_B, NCERT_C, NCERT_D), (EASY_A, EASY_B, EASY_C, EASY_D), (MED_A, MED_B, MED_C, MED_D), (HARD_A, HARD_B, HARD_C, HARD_D))
